/* Category-scoped film carousel. The queue tail travels around a closed lower arc. */
(() => {
 'use strict';
 const M=window.Studio,A=window.Art,V=window.Views,Q=window.FilmQueue;
 let lastId=null,lastCategory=null,animations=[],generation=0,queue=[];
 const n=i=>String(i+1).padStart(2,'0');
 const group=c=>M.items.filter(i=>i.category===c.item.category);
 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
 function photo(item){return `<span class="archive-photo">${A.object({itemId:item.id},true)}<span class="photo-grain" aria-hidden="true"></span></span>`;}
 function face(c){return `<div class="caption-face"><div class="archive-kicker">${M.category(c.item.category).name}系列<span> / </span>原创示意</div><h2 class="archive-name"><button class="archive-info" data-action="detail" aria-label="查看${c.item.name}的物件介绍">${c.item.name}${A.icon('chevron',12)}</button></h2></div>`;}
 function cta(c){return `${V.btn(`<span>用「${c.item.name}」共创</span>${A.icon('arrow',16)}`,'start')}${V.btn('用自己的图像开始','upload-home','text')}`;}
 function deck(c){queue=Q.create(group(c).map(i=>i.id),c.item.id);return queue.map(row=>{const item=M.getItem(row.itemId);return `<button class="film-card" data-action="film-select" data-key="${row.key}" data-id="${item.id}" data-offset="${row.offset}" aria-label="选择${item.name}">${photo(item)}<span class="slide-label">${item.name}</span></button>`;}).join('');}
 function paintCard(card,row){if(card.dataset.id!==row.itemId){const item=M.getItem(row.itemId);card.innerHTML=photo(item)+`<span class="slide-label">${item.name}</span>`;card.dataset.id=item.id;card.setAttribute('aria-label',`选择${item.name}`);}}

 function home(c){window.FilmOptics?.reset();generation++;animations.forEach(a=>a.cancel());animations=[];lastId=c.item.id;lastCategory=c.item.category;const g=group(c),index=g.findIndex(i=>i.id===lastId),single=g.length===1;return `<section class="home-screen film-home"><div class="home-intro"><div><span class="eyebrow">THE RE:BORN ARCHIVE</span><h1>从一件旧物开始</h1></div><div class="archive-tools">${V.ib('grid','browse','浏览全部物件')}${V.ib('search','search','问一问，查找物件')}</div></div><div class="film-gallery" id="object-stage" role="region" aria-label="${M.category(c.item.category).name}系列观片器，左右滑动仅浏览本系列" tabindex="0" data-material="${c.item.category}"><div class="film-deck">${deck(c)}</div><div class="viewer-shadow" aria-hidden="true"></div><div class="film-viewer"><div class="viewer-top" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><button class="viewer-window" data-action="detail" aria-label="查看${c.item.name}的物件介绍"><span class="viewed-slide" data-id="${c.item.id}">${photo(c.item)}</span><span class="glass-reflection" aria-hidden="true"></span></button><div class="viewer-base"><i class="viewer-lamp" aria-hidden="true"></i><span class="viewer-number">${n(index)}</span></div><div class="feed-arm left" aria-hidden="true"></div><div class="feed-arm right" aria-hidden="true"></div><i class="material-fastener tl" aria-hidden="true"></i><i class="material-fastener tr" aria-hidden="true"></i><i class="material-fastener bl" aria-hidden="true"></i><i class="material-fastener br" aria-hidden="true"></i></div><div id="archive-caption" aria-live="polite"><div class="caption-orbit">${face(c)}</div></div><div class="gallery-controls">${V.ib('back','prev','上一件物品',single?'disabled':'')}<span class="reel-progress"><b>${n(index)}</b><i></i><span>${n(g.length-1)}</span></span>${V.ib('arrow','next','下一件物品',single?'disabled':'')}</div><span class="gesture-hint">${single?'本系列暂有 1 件 · 可点选其他品类':'左右轻划 · 浏览本系列'}</span></div><div class="category-bar"><div class="category-scroll" role="group" aria-label="物件类别">${M.categories.map(cat=>`<button data-action="category" data-id="${cat.id}" aria-pressed="${cat.id===c.item.category}">${cat.name}</button>`).join('')}</div>${V.ib('heart','favorite',c.s.favorites.includes(c.item.id)?'取消收藏':'收藏物件',`aria-pressed="${c.s.favorites.includes(c.item.id)}"`)}</div><div class="home-cta">${cta(c)}</div><p class="home-source">自绘示意素材 · 馆藏对应待核实</p></section>`;}
 function pose(d,width){const f=Math.min(1,width/390),a=Math.abs(d);return{x:Math.sign(d)*(75*Math.min(1,a)+Math.max(0,a-1)*44)*f,y:a*a*7,rotation:Math.sign(d)*Math.min(a*11,33),scale:1-Math.min(a,3)*.035,opacity:a===0?0:Math.max(.08,.98-a*.10-a*a*.05),blur:Math.pow(Math.max(0,a-1),1.6)*.7};}

 function transform(p){return `translate3d(${p.x}px,${p.y}px,0) rotate(${p.rotation}deg) scale(${p.scale})`;}
 function apply(card,p,d){card.style.transform=transform(p);card.style.opacity=d===0?0:p.opacity;card.style.filter=`blur(${p.blur||0}px)`;card.style.zIndex=String(5-Math.abs(d));card.dataset.offset=d;card.tabIndex=d===0?-1:0;card.setAttribute('aria-hidden',String(d===0));}
 function layout(c,drag=0,skipOptics=false){const root=document.querySelector('.film-gallery');if(!root)return;const g=group(c);if(g.length<2)drag=0;window.Frame3D?.attach(root.querySelector('.film-viewer'),c.item.category,drag);root.dataset.drag=drag;const win=root.querySelector('.viewer-window');if(!skipOptics){if(drag&&g.length>1){const index=g.findIndex(i=>i.id===c.item.id),next=g[(index+(drag<0?1:-1)+g.length)%g.length];window.FilmOptics?.drag(win,c.item,next,drag,photo);}else window.FilmOptics?.release(win);}const nearest=new Map();[...queue].sort((a,b)=>Math.abs(a.offset)-Math.abs(b.offset)).forEach(row=>{if(!nearest.has(row.itemId))nearest.set(row.itemId,row.key);});root.querySelectorAll('.film-card').forEach(card=>{const row=queue.find(row=>row.key===Number(card.dataset.key));if(!row)return;paintCard(card,row);apply(card,pose(row.offset+Math.max(-.86,Math.min(.86,drag/150)),root.clientWidth),row.offset);const clone=nearest.get(row.itemId)!==row.key,hidden=clone||row.offset===0||g.length===1;card.dataset.clone=String(clone);card.dataset.single=String(g.length===1);card.tabIndex=hidden?-1:0;card.setAttribute('aria-hidden',String(hidden));});root.classList.toggle('dragging',Boolean(drag));}

 function run(el,frames,options={}){const a=el.animate(frames,{duration:860,easing:'cubic-bezier(.2,.68,.22,1)',...options});animations.push(a);return a;}
 function rollCaption(c,dir,animate,token){const orbit=document.querySelector('.caption-orbit'),previous=orbit.querySelector('.caption-face');orbit.innerHTML=face(c);if(!animate)return;const current=orbit.firstElementChild;previous.setAttribute('aria-hidden','true');previous.querySelectorAll('button').forEach(b=>b.tabIndex=-1);previous.classList.add('leaving');orbit.append(previous);run(previous,[{transform:'rotateX(0deg)',opacity:1,filter:'blur(0px)'},{transform:`rotateX(${dir*105}deg)`,opacity:0,filter:'blur(2px)'}],{duration:760,fill:'forwards'}).finished.then(()=>{if(token===generation)previous.remove();}).catch(()=>{});run(current,[{transform:`rotateX(${-dir*105}deg)`,opacity:0,filter:'blur(2px)'},{transform:'rotateX(0deg)',opacity:1,filter:'blur(0px)'}],{duration:760});}
 function sync(c,requestedDirection=0){const gallery=document.querySelector('.film-gallery');if(!gallery)return;const g=group(c),index=g.findIndex(i=>i.id===c.item.id),categoryChanged=lastCategory!==c.item.category,changed=lastId!==c.item.id,oldIndex=g.findIndex(i=>i.id===lastId);let delta=categoryChanged?0:(index-oldIndex+g.length)%g.length;if(delta>g.length/2)delta-=g.length;const step=categoryChanged?0:(requestedDirection||delta),dir=Math.sign(step)||1,animate=(changed||step!==0)&&!reduced(),token=++generation;const oldQueue=queue.map(row=>({...row}));
 const oldTransforms=new Map([...gallery.querySelectorAll('.film-card')].map(el=>{const style=getComputedStyle(el),matrix=new DOMMatrixReadOnly(style.transform);return[Number(el.dataset.key),{transform:style.transform,opacity:style.opacity,pose:{x:matrix.m41,y:matrix.m42,rotation:Math.atan2(matrix.m12,matrix.m11)*180/Math.PI,scale:Math.hypot(matrix.m11,matrix.m12),opacity:Number(style.opacity),blur:parseFloat(style.filter.match(/blur\(([^)]+)/)?.[1])||0}}];}));animations.forEach(a=>a.cancel());animations=[];
 if(categoryChanged)gallery.querySelector('.film-deck').innerHTML=deck(c);else if(step)queue=Q.advance(queue,g.map(i=>i.id),c.item.id,step);
 gallery.dataset.material=c.item.category;gallery.setAttribute('aria-label',`${M.category(c.item.category).name}系列观片器，左右滑动仅浏览本系列`);layout(c,0,true);
 if(animate&&!categoryChanged){const center=gallery.querySelector('.film-viewer').getBoundingClientRect(),controls=gallery.querySelector('.gallery-controls').getBoundingClientRect(),lower=controls.top-(center.top+center.height/2)-29;gallery.querySelectorAll('.film-card').forEach(card=>{const key=Number(card.dataset.key),a=oldQueue.find(row=>row.key===key).offset,b=queue.find(row=>row.key===key).offset,start=oldTransforms.get(key)?.pose||pose(a,gallery.clientWidth),end=pose(b,gallery.clientWidth),wrap=dir>0?b>a:b<a,frames=[];for(let k=0;k<=32;k++){const t=k/32;let p;if(wrap){const travel=(1-Math.cos(t*Math.PI))/2;p={x:start.x+(end.x-start.x)*travel,y:start.y+(end.y-start.y)*t+Math.sin(t*Math.PI)*(lower-(start.y+end.y)/2),rotation:start.rotation+(end.rotation-start.rotation)*travel,scale:start.scale+(end.scale-start.scale)*t-Math.sin(t*Math.PI)*.06,opacity:.98};}else{p={x:start.x+(end.x-start.x)*t,y:start.y+(end.y-start.y)*t,rotation:start.rotation+(end.rotation-start.rotation)*t,scale:start.scale+(end.scale-start.scale)*t,opacity:start.opacity+(end.opacity-start.opacity)*t};}const targetOpacity=b===0?0:end.opacity,opacity=Math.min(1,start.opacity+(targetOpacity-start.opacity)*t+(wrap?Math.sin(t*Math.PI)*.35:0));const blur=Math.max(0,(start.blur||0)+(end.blur-(start.blur||0))*t-(wrap?Math.sin(t*Math.PI)*1.8:0));frames.push({offset:t,transform:transform(p),opacity,filter:`blur(${blur}px)`});}if(oldTransforms.has(key)){frames[0].transform=oldTransforms.get(key).transform;frames[0].opacity=oldTransforms.get(key).opacity;}if(wrap)card.style.zIndex='7';run(card,frames).finished.then(()=>{if(token===generation)card.style.zIndex=String(5-Math.abs(b));}).catch(()=>{});});}
 const win=gallery.querySelector('.viewer-window');win.setAttribute('aria-label',`查看${c.item.name}的物件介绍`);
 window.FilmOptics.transition(win,c.item,dir,photo,{animate:changed&&animate,categoryChanged});
 rollCaption(c,dir,animate&&!categoryChanged,token);lastId=c.item.id;lastCategory=c.item.category;
 gallery.querySelector('.viewer-number').textContent=n(index);gallery.querySelector('.reel-progress b').textContent=n(index);gallery.querySelector('.reel-progress>span').textContent=n(g.length-1);gallery.querySelectorAll('.gallery-controls button').forEach(b=>b.disabled=g.length<2);gallery.querySelector('.gesture-hint').textContent=g.length<2?'本系列暂有 1 件 · 可点选其他品类':'左右轻划 · 浏览本系列';document.querySelector('.home-cta').innerHTML=cta(c);document.querySelectorAll('.category-scroll button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===c.item.category)));const fav=document.querySelector('.category-bar [data-action=favorite]');fav.setAttribute('aria-pressed',String(c.s.favorites.includes(c.item.id)));fav.setAttribute('aria-label',c.s.favorites.includes(c.item.id)?'取消收藏':'收藏物件');
 }
 V.home=home;window.FilmHome={layout,sync};
})();
